'use strict';

// MODULES //

var LinearScale = require( '@stdlib/plot/vega/scale/linear' );
var LogScale = require( '@stdlib/plot/vega/scale/log' );
var PowerScale = require( '@stdlib/plot/vega/scale/power' );
var SqrtScale = require( '@stdlib/plot/vega/scale/sqrt' );
var SymLogScale = require( '@stdlib/plot/vega/scale/symmetric-log' );
var TimeScale = require( '@stdlib/plot/vega/scale/time' );
var UTCScale = require( '@stdlib/plot/vega/scale/utc' );


// MAIN //

// Mapping from scale types to scale constructors...
var ctors = {
	'linear': LinearScale,
	'log': LogScale,
	'pow': PowerScale,
	'sqrt': SqrtScale,
	'symlog': SymLogScale,
	'time': TimeScale,
	'utc': UTCScale
};


// EXPORTS //

module.exports = ctors;
